<script setup lang="ts">
import {ref} from 'vue'
import {downloadFile} from '../downloadFile'
const props=defineProps<{base:string;token:string;courseId?:string;admin?:boolean}>()
const search=ref(''),days=ref(7),attention=ref('all'),logType=ref('audits'),busy=ref(false),error=ref('')
async function download(kind:string){if(busy.value)return;busy.value=true;error.value='';try{await downloadFile(props.base,props.token,props.courseId?`/courses/${props.courseId}/exports/${kind}?search=${encodeURIComponent(search.value)}&attention=${attention.value}`:`/admin/exports/${logType.value}?days=${days.value}&search=${encodeURIComponent(search.value)}`)}catch(e){error.value=e instanceof Error?e.message:'导出失败'}finally{busy.value=false}}
</script>
<template><section class="data-exports"><h3>{{courseId?'课程数据导出':'操作日志导出'}}</h3><div class="export-fields"><label v-if="!courseId">日志类型<select v-model="logType"><option value="audits">管理操作</option><option value="logins">登录记录</option><option value="requests">请求记录</option></select></label><label>{{courseId?'学生姓名、账号或作业':logType==='audits'?'操作人或操作名称':logType==='logins'?'登录账号':'请求方法或路径'}}<input v-model="search" maxlength="100" placeholder="留空导出全部结果"/></label><label v-if="!courseId">时间范围<select v-model="days"><option :value="1">最近1天</option><option :value="7">最近7天</option><option :value="30">最近30天</option><option :value="90">最近90天</option></select></label><label v-else>学情范围<select v-model="attention"><option value="all">全部学生</option><option value="overdue">逾期未交</option><option value="low_score">低于60分</option><option value="ungraded">待批改</option><option value="no_grades">暂无成绩</option></select></label></div><div class="export-buttons"><button v-if="courseId" :disabled="busy" @click="download('grades')">导出作业成绩</button><button v-if="courseId" :disabled="busy" @click="download('analytics')">导出筛选学情</button><button v-else :disabled="busy" @click="download('audits')">下载日志 CSV</button></div><p v-if="busy" role="status"><span class="ui-spinner"/>正在导出…</p><p v-if="error" role="alert">{{error}}</p></section></template>
<style scoped>.data-exports{padding:14px 0;border-top:1px solid #e0e8f4;margin-top:16px}.export-fields{display:flex;flex-wrap:wrap;gap:12px}.export-fields label{display:grid;gap:6px;font-size:12px;flex:1;min-width:130px}.export-buttons{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.export-buttons button{font-size:12px;min-height:40px}.data-exports p{font-size:12px}</style>
